package par2

import "sync"

// Arithmetic in GF(2^16) as PAR 2.0 defines it: the field is generated by
// the polynomial x^16 + x^12 + x^3 + x + 1 (0x1100B), with 2 as the
// generator. Addition is XOR.

const (
	gfPoly = 0x1100B
	// gfOrder is the size of the multiplicative group.
	gfOrder = 65535
	// maxInputSlices is the number of usable input slice constants: the
	// logarithms below 65535 that share no factor with it (3, 5, 17, 257).
	maxInputSlices = 32768
)

type field struct {
	// exp is doubled so exp[a+b] needs no reduction for logs below 65535.
	exp [2 * gfOrder]uint16
	log [1 << 16]uint32
	// inputLogs[i] is the logarithm of input slice i's constant.
	inputLogs [maxInputSlices]uint32
}

var gf = sync.OnceValue(newField)

func newField() *field {
	f := &field{}

	x := uint32(1)
	for i := range gfOrder {
		f.exp[i] = uint16(x)
		f.exp[i+gfOrder] = uint16(x)
		f.log[x] = uint32(i)

		x <<= 1
		if x&0x10000 != 0 {
			x ^= gfPoly
		}
	}

	n := 0
	for l := uint32(0); n < maxInputSlices; l++ {
		if l%3 != 0 && l%5 != 0 && l%17 != 0 && l%257 != 0 {
			f.inputLogs[n] = l
			n++
		}
	}

	return f
}

func (f *field) mul(a, b uint16) uint16 {
	if a == 0 || b == 0 {
		return 0
	}

	return f.exp[f.log[a]+f.log[b]]
}

// inv returns 1/a; a must not be zero.
func (f *field) inv(a uint16) uint16 { return f.exp[gfOrder-f.log[a]] }

// coefficient returns input slice i's constant raised to exponent e, the
// factor of slice i in recovery slice e.
func (f *field) coefficient(i int, e uint32) uint16 {
	return f.exp[uint64(f.inputLogs[i])*uint64(e)%gfOrder]
}

// mulTable multiplies 16-bit words by one constant: c*w is
// lo[w&0xff] ^ hi[w>>8].
type mulTable struct {
	lo, hi [256]uint16
}

// table fills t for c. Multiplication is linear over XOR, so each entry is
// one XOR away from a smaller one.
func (f *field) table(c uint16, t *mulTable) {
	t.lo[0], t.hi[0] = 0, 0

	for k := range 8 {
		lo, hi := f.mul(c, 1<<k), f.mul(c, 1<<(k+8))

		for b := range 1 << k {
			t.lo[1<<k+b] = lo ^ t.lo[b]
			t.hi[1<<k+b] = hi ^ t.hi[b]
		}
	}
}

// mulAdd adds c*src to dst word by word, where t is c's table.
func mulAdd(dst, src []uint16, t *mulTable) {
	dst = dst[:len(src)]
	for i, w := range src {
		dst[i] ^= t.lo[w&0xff] ^ t.hi[w>>8]
	}
}
